function applyDiscount(order) {
  if (order.total > 1000) return applyPercent(order, 10);
  if (order.customer.isPreferred) return applyPercent(order, 5);
  return applyFixed(order, 20);
}

// Version B
function applyDiscount(order, flags) {
  let discount = 0;
  if (flags.usePercent && order.total > 1000) discount = 10;
  if (flags.preferred && order.customer.isPreferred) discount = Math.max(discount, 5);
  if (!discount) discount = 20;
  // further nested flag handling
  return finalizeDiscount(order, discount);
}
